useNoticeStore pseudocode:
interface NoticeState { notices: Notice[]; isLoading: boolean; setNotices: (n: Notice[]) => void; setLoading: (b: boolean) => void; clearNotice: () => void; }
export const useNoticeStore = create<NoticeState>(set => ({ notices: [], isLoading: false, setNotices: n => set({notices: n}), setLoading: b => set({isLoading: b}), clearNotice: () => set({notices: [], isLoading: false}) }))

useNotificationStore pseudocode:
interface NotifState { notifications: AppNotification[]; unreadCount: number; isLoading: boolean; setNotifications: (n: AppNotification[]) => void; markAsRead: (id: string) => void; clearNotifications: () => void; }
markAsRead: updateDoc + set(state => ({ notifications: state.notifications.map(n => n.id===id ? {...n,is_read:true} : n), unreadCount: Math.max(0, state.unreadCount-1) }))
